Arguments: {"cwd":null,"title":"Analyze NBA Spring Schedule","code":"const tabId = 103795220;
const scheduleAnalysis = await browserjs(tabId, async () => {
  const res = await fetch('https://cdn.nba.com/static/json/staticData/scheduleLeagueV2_1.json');
  const data = await res.json();
  const gameDates = data.leagueSchedule.gameDates;

  // Let's inspect the dates range and structure of a game
  const firstDate = gameDates[0].gameDate;
  const lastDate = gameDates[gameDates.length - 1].gameDate;

  // Find dates in March and April
  const springDates = gameDates.filter(gd => {
    const d = gd.gameDate; // e.g. "03/01/2027" or similar
    return d.startsWith("03/") || d.startsWith("04/");
  });

  // Sample game structure
  const sampleGame = springDates[0]?.games?.[0];

  // Check teams represented as home teams in spring
  const homeTeamsInSpring = new Set();
  springDates.forEach(gd => {
    gd.games.forEach(g => {
      homeTeamsInSpring.add(g.homeTeam.teamName + " (" + g.homeTeam.teamCity + ")");
    });
  });

  return {
    totalDates: gameDates.length,
    firstDate,
    lastDate,
    springDatesCount: springDates.length,
    totalSpringGames: springDates.reduce((acc, gd) => acc + gd.games.length, 0),
    homeTeamsCount: homeTeamsInSpring.size,
    sampleGame: {
      gameId: sampleGame?.gameId,
      gameCode: sampleGame?.gameCode,
      gameDateTimeUTC: sampleGame?.gameDateTimeUTC,
      gameDateTimeEst: sampleGame?.gameDateTimeEst,
      homeTeam: sampleGame?.homeTeam,
      awayTeam: sampleGame?.awayTeam,
      arenaName: sampleGame?.arenaName,
      arenaCity: sampleGame?.arenaCity,
      arenaState: sampleGame?.arenaState
    }
  };
});
console.log("Schedule Analysis:", JSON.stringify(scheduleAnalysis, null, 2));
"}
