Arguments: {"title":"Extract all 30 teams and star games","code":"const tabId = 103795220;
const analysis = await browserjs(tabId, async () => {
  const res = await fetch('https://cdn.nba.com/static/json/staticData/scheduleLeagueV2_1.json');
  const data = await res.json();
  const gameDates = data.leagueSchedule.gameDates;

  // Filter for spring games (March and April)
  const allSpringGames = [];
  gameDates.forEach(gd => {
    const dStr = gd.gameDate; // e.g. "03/01/2027 00:00:00"
    if (dStr.startsWith("03/") || dStr.startsWith("04/")) {
      const dateOnly = dStr.split(" ")[0]; // "03/01/2027"
      gd.games.forEach(g => {
        allSpringGames.push({
          date: dateOnly,
          gameId: g.gameId,
          gameCode: g.gameCode,
          gameDateTimeEst: g.gameDateTimeEst,
          homeTeam: g.homeTeam.teamName,
          homeCity: g.homeTeam.teamCity,
          homeTricode: g.homeTeam.teamTricode,
          awayTeam: g.awayTeam.teamName,
          awayCity: g.awayTeam.teamCity,
          awayTricode: g.awayTeam.teamTricode,
          arenaName: g.arenaName,
          arenaCity: g.arenaCity,
          arenaState: g.arenaState,
          isStarGame: ['LAL', 'GSW', 'SAS'].includes(g.homeTeam.teamTricode) || ['LAL', 'GSW', 'SAS'].includes(g.awayTeam.teamTricode),
          starTeam: ['LAL', 'GSW', 'SAS'].find(t => t === g.homeTeam.teamTricode || t === g.awayTeam.teamTricode) || null
        });
      });
    }
  });

  // Group by home team (arena)
  const byHomeTeam = {};
  allSpringGames.forEach(g => {
    const key = `${g.homeCity} ${g.homeTeam}`;
    if (!byHomeTeam[key]) {
      byHomeTeam[key] = {
        arena: g.arenaName,
        city: g.arenaCity,
        state: g.arenaState,
        tricode: g.homeTricode,
        games: []
      };
    }
    byHomeTeam[key].games.push(g);
  });

  return {
    totalSpringGames: allSpringGames.length,
    teamsCount: Object.keys(byHomeTeam).length,
    teams: Object.keys(byHomeTeam).map(team => ({
      team,
      arena: byHomeTeam[team].arena,
      city: byHomeTeam[team].city,
      state: byHomeTeam[team].state,
      gameCount: byHomeTeam[team].games.length,
      starGames: byHomeTeam[team].games.filter(g => g.isStarGame).map(g => `${g.date}: vs ${g.awayTricode} (Star: ${g.starTeam})`)
    }))
  };
});

console.log("Teams count:", analysis.teamsCount);
console.log("Sample teams and their star games:");
analysis.teams.slice(0, 10).forEach(t => {
  console.log(`${t.team} (${t.arena}, ${t.city}): ${t.gameCount} home games, star games:`, t.starGames);
});
