    } else if (fromCity === "Brooklyn" && toCity === "Boston") {
      mode = "Drive / Amtrak";
      cost = 40;
      details = "Drive 215 mi via I-95/I-84 (4h, ~$35 gas/tolls) or Amtrak from Moynihan (4h, ~$45)";
    } else if (fromCity === "Cleveland" && toCity === "Brooklyn") {
      mode = "Fly / Drive";
      // Cleveland to NYC is 460 miles (~7 hrs drive) or 1.5 hr flight
      cost = 95;
      mode = "Fly (or Drive)";
      details = "Nonstop flight CLE-JFK/LGA (1.5h, ~$95) or road trip drive 460 mi via I-80 (7h, ~$65 gas)";
    } else if (roadMiles <= 260) {
      mode = "Drive";
      cost = driveGasCost;
      details = `Drive ${roadMiles} mi (${driveHours}h, ~$${driveGasCost} gas/tolls) - cheaper & faster door-to-door than flying`;
    } else if (roadMiles <= 400 && driveHours <= 6) {
      mode = "Drive";
      cost = driveGasCost;
      details = `Drive ${roadMiles} mi (${driveHours}h, ~$${driveGasCost} gas) - great road trip leg; flying ~$${flightCost}`;
    } else {
      mode = "Fly";
      cost = flightCost;
      details = `Flight (${flightHours}h total, ~$${flightCost}) - driving ${roadMiles} mi (${driveHours}h) is impractical on tight schedule`;
    }

    legs.push({
      stop: i + 1,
      fromCity,
      toCity,
      date: stops[i].date,
      roadMiles,
      driveHours,
      driveGasCost,
      flightCost,
      flightHours,
      cheapestMode: mode,
      cost,
      details
    });
  }
}

