  const l = legs[i];
  const h = hotels[i];
  const f = food[i];

  const travelCost = l.cost || 0;
  const hotelCost = h.price || 0;
  const legTotal = travelCost + hotelCost;
  runningTotal += legTotal;

  const starStr = s.starPlayer ? `★ **${s.starPlayer}**` : "Regular Matchup";
  const travelStr = l.fromCity ? `${l.fromCity} ➔ ${l.toCity} (${l.cheapestMode})` : "Trip Origin (Houston)";
  const hotelStr = `${h.hotel} ($${hotelCost}/nt)`;
  const foodStr = `${f.restaurant} (${f.specialty.split('(')[0].trim()})`;

  md += `| **#${i + 1}** | ${s.date} | **${s.arenaName}**<br>${s.arenaCity}, ${s.arenaState} | ${s.homeTeam} vs.<br>${s.awayTeam} | ${starStr} | ${travelStr}<br>_${l.details}_ | $${travelCost} | ${hotelStr} | ${foodStr} | **$${runningTotal}** |\n`;
}

